export default async (ctx, client) => {
  const rows = await client.query(
    `SELECT platform, kind, COUNT(*)::int AS n, MAX(updated_at) AS latest
     FROM conversations
     WHERE organization_id = $1
     GROUP BY platform, kind
     ORDER BY n DESC`,
    [ctx.organization_id]
  );
  return { org: ctx.organization_id, rows };
}

export default async (ctx, client) => {
  const agents = await client.agents.list();
  const ids = (agents?.agents ?? agents ?? []).map(a => a.id ?? a.agent_id).filter(Boolean);
  const out = [];
  for (const agentId of ids.slice(0, 8)) {
    try {
      const convs = await client.conversations.list({ agent_id: agentId, scope: "all", limit: 50 });
      const list = convs?.conversations ?? convs ?? [];
      const byPlatform = {};
      for (const c of list) {
        const p = c.platform ?? "?";
        byPlatform[p] = (byPlatform[p] ?? 0) + 1;
      }
      out.push({ agentId, total: list.length, byPlatform });
    } catch (e) {
      out.push({ agentId, error: String(e?.message ?? e) });
    }
  }
  return { org: ctx.organization_id, agents: ids.length, out };
}

