}

/**
 * Revoke an MCP client's access: kills its live tokens and MCP sessions.
 *
 * `scope: "all"` extends that to every other registration of the same client
 * (same name + user + org). A client that re-registers gets a NEW row each
 * time, so revoking a single id can leave the same app connected through its
 * siblings — which reads as "I disconnected it and it's still there".
 *
 * Owner/admin only; the server returns 403 for anyone else.
 */
export function useRevokeMcpClient() {
	const { slug } = getPathScope();
	const queryClient = useQueryClient();

	return useMutation({
		mutationFn: async (vars: { clientId: string; scope?: "all" }) => {
			const params = new URLSearchParams();
			if (vars.scope === "all") params.set("scope", "all");

			const res = await fetchWithTimeout(
				clientsUrl(slug!, `/mcp/${encodeURIComponent(vars.clientId)}`, params),
				{ method: "DELETE", credentials: "include" },
			);
			await throwIfNotOk(res, "Failed to revoke client");
			return (await res.json()) as { revokedClientIds?: string[] };
		},
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ["connected-clients", slug] });
		},
	});
}

