/**
 * Grouping connected clients for display.
 *
 * The clients API returns one row per oauth_clients registration, and a client
 * that re-registers gets a NEW row under the same name (prod: "Lobu CLI" has 6
 * ids). Listing them raw shows the same app six times and makes "Revoke"
 * ambiguous, so the page collapses registrations into one row per app while
 * keeping every id for the revoke fan-out.
 */

import { describe, expect, it } from "vitest";
import {
	type ClientGroup,
	groupClients,
} from "@/app/$owner/infrastructure/clients";
import type { ConnectedClientItem } from "@/lib/api/clients";

function mcp(
	over: Partial<ConnectedClientItem> & { id: string },
): ConnectedClientItem {
	return {
		kind: "mcp",
		status: "disconnected",
		authState: "revoked",
		...over,
	} as ConnectedClientItem;
}

describe("groupClients", () => {
	it("collapses re-registrations of the same app into one row", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "Lobu CLI", lastSeenAt: 100 }),
			mcp({ id: "b", title: "Lobu CLI", lastSeenAt: 300 }),
			mcp({ id: "c", title: "Lobu CLI", lastSeenAt: 200 }),
		]);

		expect(groups).toHaveLength(1);
		expect(groups[0].clientIds.sort()).toEqual(["a", "b", "c"]);
	});

	it("keeps every id so revoke can fan out across registrations", () => {
		// This is the whole point of grouping: the row shows one app, but
		// disconnecting it has to reach all of its registrations.
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT" }),
			mcp({ id: "b", title: "ChatGPT" }),
		]);
		expect(groups[0].clientIds).toHaveLength(2);
	});

	it("does not merge different apps", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT" }),
			mcp({ id: "b", title: "Claude" }),
		]);
		expect(groups).toHaveLength(2);
	});

	it("does not merge the same app name across different people", () => {
		// Registrations are per-user; collapsing across users would let one
		// person's Revoke silently disconnect another person's client.
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT", linkedUserEmail: "x@example.com" }),
			mcp({ id: "b", title: "ChatGPT", linkedUserEmail: "y@example.com" }),
		]);
		expect(groups).toHaveLength(2);
	});

	it("shows the group as connected when ANY registration is live", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT", status: "disconnected" }),
			mcp({ id: "b", title: "ChatGPT", status: "connected" }),
		]);
		expect(groups[0].connected).toBe(true);
	});

	it("reports the most recent activity across registrations", () => {
		const groups = groupClients([
			mcp({ id: "a", title: "ChatGPT", lastSeenAt: 100 }),
			mcp({ id: "b", title: "ChatGPT", lastSeenAt: 900 }),
		]);
		expect(groups[0].lastSeenAt).toBe(900);
	});

	it("never collapses messaging clients — they are one row per person", () => {
		const groups = groupClients([
			{ id: "ag:telegram:1", kind: "messaging", title: "same" },
			{ id: "ag:telegram:2", kind: "messaging", title: "same" },
		] as ConnectedClientItem[]);
		expect(groups).toHaveLength(2);
	});

	it("orders by most recently active", () => {
		const groups: ClientGroup[] = groupClients([
			mcp({ id: "a", title: "Older", lastSeenAt: 100 }),
			mcp({ id: "b", title: "Newer", lastSeenAt: 900 }),
		]);
		expect(groups.map((g) => g.title)).toEqual(["Newer", "Older"]);
	});
});

