9	/**
10	 * Legacy / deep-link path form. Everything memory-related is now an in-place
11	 * scope on `/memory` (the tab bar never disappears), so this route only
12	 * redirects: a bare `/memory/<type>` → `?type=<slug>`, an entity path
13	 * `/memory/<type>/<slug>[/…]` → `?entity=<path>`.
14	 */
15	export const Route = createFileRoute("/$owner/memory/$")({
16		beforeLoad: ({ params }) => {
17			const splat = parseMemorySplat(params._splat || "");
18			if (!splat.typeSegment) {
19				throw redirect({
20					to: "/$owner/memory",
21					params: { owner: params.owner },
22					search: {},
23					replace: true,
24				});
25			}
26			if (isReservedOwnerSegment(splat.typeSegment)) {
27				throw notFound();
28			}
29			throw redirect({
30				to: "/$owner/memory",
31				params: { owner: params.owner },
32				// One scope at a time: an entity path → ?entity= only (its type is
33				// derived); a bare type → ?type=.
34				search: splat.isEntityDetail
35					? {
36							entity: splat.path
37								? decodeEntityBrowsePath(splat.path)
38								: undefined,
39						}
40					: {
41							type: splat.typeSegment
42								? decodeEntityTypeParam(splat.typeSegment)
43								: undefined,
44						},
45				replace: true,
46			});
47		},
48		component: () => null,
49	});
