		const link = memoryBrowseTypeSearch(ownerSlug, typeSlug);
		// `memoryBrowseTypeSearch` clears stale `?entity=` scopes.
		void navigate({
			to: link.to,
			params: link.params,
			search: pruneSearch({
				...link.search,
				create: open ? "true" : undefined,
			}) as Record<string, string | undefined>,
			replace: true,
		});
	};

	const paneBody = (
		<>
			{entityNotFound ? (
				<TabEmptyState
					icon={Boxes}
					title="Entity not found"
					description="This entity no longer exists. Clear the selection to keep browsing."
				/>
