import { describe, expect, it } from "vitest";
import { isOwnerSectionActive, OWNER_SECTIONS } from "./owner-sections";

describe("OWNER_SECTIONS", () => {
	it("orders the site map: activity, connect, memory", () => {
		expect(Object.keys(OWNER_SECTIONS)).toEqual([
			"activity",
			"connectors",
			"context",
		]);
	});

	// Activity is the org-wide Events stream on its own page.
	it("routes Activity to /activity", () => {
		expect(OWNER_SECTIONS.activity).toEqual(
			expect.objectContaining({
				label: "Activity",
				to: "/$owner/activity",
				segment: "activity",
			}),
		);
	});

	// Memory is the entity types/records surface (formerly labeled Context).
	it("routes Memory to /memory", () => {
		expect(OWNER_SECTIONS.context).toEqual(
			expect.objectContaining({
				label: "Memory",
				to: "/$owner/memory",
				segment: "memory",
				search: {},
			}),
		);
	});

	it("routes Connect to /connectors", () => {
		expect(OWNER_SECTIONS.connectors).toEqual(
			expect.objectContaining({
				label: "Connect",
				to: "/$owner/connectors",
				segment: "connectors",
			}),
		);
	});
});

describe("isOwnerSectionActive", () => {
	const owner = "acme";

	it("lights Activity on /activity only", () => {
		expect(isOwnerSectionActive("activity", owner, "/acme/activity")).toBe(
			true,
		);
		expect(isOwnerSectionActive("activity", owner, "/acme/memory")).toBe(false);
		expect(isOwnerSectionActive("context", owner, "/acme/activity")).toBe(
			false,
		);
	});

	it("lights Memory on /memory and splat detail paths", () => {
		expect(isOwnerSectionActive("context", owner, "/acme/memory")).toBe(true);
		expect(
			isOwnerSectionActive("context", owner, "/acme/memory/person/alice"),
		).toBe(true);
		expect(
			isOwnerSectionActive("activity", owner, "/acme/memory/person/alice"),
		).toBe(false);
	});

	it("lights Connect on any /connectors path", () => {
		expect(isOwnerSectionActive("connectors", owner, "/acme/connectors")).toBe(
			true,
		);
		expect(
			isOwnerSectionActive("connectors", owner, "/acme/connectors/slack"),
		).toBe(true);
		expect(isOwnerSectionActive("activity", owner, "/acme/connectors")).toBe(
			false,
		);
	});

	it("does not light a section on a mere prefix segment", () => {
		expect(
			isOwnerSectionActive("activity", owner, "/acme/activity-feed"),
		).toBe(false);
	});
});

import { describe, expect, it } from "vitest";
import {
	buildMemoryEntityScopePath,
	canonicalMemorySearch,
	connectorForConnectionIds,
	entityPathToBrowsePath,
	memoryBrowseEntitySearch,
	memoryBrowseHomeSearch,
	memoryBrowseTypeSearch,
	memoryEventsFilterSearch,
	memoryFeedDrillSearch,
	memoryMemberListSearch,
	memorySearchNeedsCanonicalRedirect,
	memoryWatcherDrillSearch,
	parseConnectionScope,
	parseEntityScope,
	parseMemorySplat,
} from "./memory-browse";

describe("parseMemorySplat", () => {
	it("parses an empty splat as the memory home", () => {
		expect(parseMemorySplat("")).toEqual({ isEntityDetail: false });
		expect(parseMemorySplat(undefined)).toEqual({ isEntityDetail: false });
	});

	it("parses a bare type segment (entity list)", () => {
		expect(parseMemorySplat("company")).toEqual({
			typeSegment: "company",
			path: "company",
			isEntityDetail: false,
		});
	});

	it("parses a type/slug path as entity detail", () => {
		expect(parseMemorySplat("company/acme-corp")).toEqual({
			typeSegment: "company",
			path: "company/acme-corp",
			isEntityDetail: true,
		});
	});

	it("strips surrounding slashes", () => {
		expect(parseMemorySplat("/person/alice/")).toEqual({
			typeSegment: "person",
			path: "person/alice",
			isEntityDetail: true,
		});
	});
});

describe("memory scope link builders", () => {
	it("scopes a type in place via ?type, clearing other scopes", () => {
		expect(memoryBrowseTypeSearch("acme", "person")).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { type: "person" },
		});
	});

	it("scopes a single entity via ?entity, clearing the type scope", () => {
		expect(
			memoryBrowseEntitySearch("acme", [
				{ entity_type: "person", slug: "alice" },
			]),
		).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { entity: "person/alice" },
		});
	});

	it("drills from a watch behavior into Activity scoped to that watcher", () => {
		expect(memoryWatcherDrillSearch("acme", "crm", "42")).toEqual({
			to: "/$owner/activity",
			params: { owner: "acme" },
			search: { agent: "crm", behavior: "42" },
		});
	});

	it("drills connector feeds into Activity", () => {
		expect(memoryFeedDrillSearch("acme", 7, { connectionScope: "3" })).toEqual({
			to: "/$owner/activity",
			params: { owner: "acme" },
			search: { feed_ids: "7", connection_ids: "3" },
		});
	});

	it("formats entity path segments for search (literal $ in type slugs)", () => {
		expect(
			entityPathToBrowsePath([
				{ entity_type: "person", slug: "alice" },
				{ entity_type: "project", slug: "lobu" },
			]),
		).toBe("person/alice/project/lobu");
		expect(
			entityPathToBrowsePath([{ entity_type: "$member", slug: "alice" }]),
		).toBe("$member/alice");
	});

	it("scopes $member via ?type= without pre-encoding %24", () => {
		expect(memoryBrowseTypeSearch("acme", "$member").search).toEqual({
			type: "$member",
		});
	});

	it("normalizes a double-encoded entity scope on read", () => {
		expect(parseEntityScope({ entity: "%24member/alice" })).toBe(
			"$member/alice",
		);
	});

	it("clears every scope on the home link", () => {
		expect(memoryBrowseHomeSearch().search).toEqual({});
	});
});

describe("canonicalMemorySearch", () => {
	it("decodes pre-encoded member entity scopes", () => {
		expect(
			canonicalMemorySearch({
				entity: "%24member/acme",
			}),
		).toEqual({ entity: "$member/acme" });
	});

	it("decodes pre-encoded type slugs", () => {
		expect(canonicalMemorySearch({ type: "%24member" })).toEqual({
			type: "$member",
		});
	});

	it("drops type when an entity scope is present", () => {
		expect(
			canonicalMemorySearch({
				type: "person",
				entity: "person/alice",
			}),
		).toEqual({ entity: "person/alice" });
	});

	it("preserves namespaced peek state alongside route filters", () => {
		expect(
			canonicalMemorySearch({
				type: "person",
				peek: "1",
				peek_run_id: "42",
			}),
		).toEqual({ type: "person", peek: "1", peek_run_id: "42" });
	});

	it("preserves create=true through canonicalization", () => {
		expect(
			canonicalMemorySearch({
				type: "$member",
				create: true,
			}),
		).toEqual({ type: "$member", create: "true" });
	});
});

describe("memorySearchNeedsCanonicalRedirect", () => {
	it("flags double-encoded entity scopes", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				entity: "%24member/alice",
			}),
		).toEqual({ entity: "$member/alice" });
	});

	it("flags stale type+entity pairs", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				type: "$member",
				entity: "$member/alice",
			}),
		).toEqual({ entity: "$member/alice" });
	});

	it("is a no-op for already-canonical member list URLs", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				type: "$member",
			}),
		).toBeNull();
	});
});

describe("memoryMemberListSearch", () => {
	it("scopes the built-in members list on memory", () => {
		expect(memoryMemberListSearch("acme")).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { type: "$member" },
		});
	});
});

describe("buildMemoryEntityScopePath", () => {
	it("builds a memory entity detail URL for refs and callbacks", () => {
		expect(
			buildMemoryEntityScopePath("acme", [
				{ entity_type: "$member", slug: "alice" },
			]),
		).toBe("/acme/memory?entity=%24member%2Falice");
	});
});

describe("memoryEventsFilterSearch", () => {
	it("adds a filter key on /activity while preserving sibling filters", () => {
		const link = memoryEventsFilterSearch(
			"acme",
			{ type: "company", connection_ids: "1" },
			{ agent: "scout" },
		);
		expect(link.to).toBe("/$owner/activity");
		expect(link.params).toEqual({ owner: "acme" });
		// The pre-existing type + connection_ids survive; agent is added.
		expect(link.search).toEqual({
			type: "company",
			connection_ids: "1",
			agent: "scout",
		});
	});

	it("clears exactly one key when its patch value is undefined", () => {
		const link = memoryEventsFilterSearch(
			"acme",
			{ type: "company", connection_ids: "1", feed_ids: "9" },
			{ feed_ids: undefined },
		);
		expect(link.search).toEqual({
			type: "company",
			connection_ids: "1",
		});
	});
});

describe("connectorForConnectionIds", () => {
	const groups = [
		{ connector_key: "slack", connections: [{ id: 1 }, { id: 2 }] },
		{ connector_key: "gmail", connections: [{ id: 3 }] },
	];

	it("returns the owning connector for a single connection", () => {
		expect(connectorForConnectionIds(groups, new Set(["3"]))).toBe("gmail");
	});

	it("returns the connector when all ids belong to one connector", () => {
		expect(connectorForConnectionIds(groups, new Set(["1", "2"]))).toBe(
			"slack",
		);
	});

	it("returns undefined when ids span more than one connector", () => {
		expect(
			connectorForConnectionIds(groups, new Set(["1", "3"])),
		).toBeUndefined();
	});

	it("returns undefined for an empty or unmatched set", () => {
		expect(connectorForConnectionIds(groups, new Set())).toBeUndefined();
		expect(
			connectorForConnectionIds(groups, new Set(["999"])),
		).toBeUndefined();
	});

	it("returns undefined when any selected id is unmatched", () => {
		expect(
			connectorForConnectionIds(groups, new Set(["1", "999"])),
		).toBeUndefined();
	});
});

