/**
 * Legacy `/memory` URLs after the Activity/Memory split: events-shaped
 * searches move to `/activity` with their filters intact; entity-detail
 * intents keep winning over stray event keys.
 */
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRouter,
	RouterProvider,
} from "@tanstack/react-router";
import { render, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { parseRouterSearch, stringifyRouterSearch } from "@/lib/router-search";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";

const OWNER = "test-org";

async function mountAt(path: string) {
	setAuthStateMock("authenticated");
	server.use(
		http.get("*/api/organizations", () =>
			HttpResponse.json({
				organizations: [
					{
						id: "org-1",
						name: "Test Org",
						slug: OWNER,
						logo: null,
						description: null,
						created_at: "2026-01-01T00:00:00.000Z",
						is_member: true,
						visibility: "private",
					},
				],
			}),
		),
	);

	const queryClient = new QueryClient({
		defaultOptions: {
			queries: { retry: false, staleTime: Number.POSITIVE_INFINITY },
		},
	});
	const { routeTree } = await import("@/routeTree.gen");
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
		context: { queryClient },
		parseSearch: parseRouterSearch,
		stringifySearch: stringifyRouterSearch,
		defaultPreload: false,
	});
	const result = render(
		<QueryClientProvider client={queryClient}>
			{/** biome-ignore lint/suspicious/noExplicitAny: memory router variant */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	await waitFor(() => {
		expect(router.state.status).toBe("idle");
	});
	return { router, ...result };
}

describe("legacy /memory → /activity redirects", () => {
	let errorSpy: ReturnType<typeof vi.spyOn>;
	beforeEach(() => {
		errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
	});
	afterEach(() => errorSpy.mockRestore());

	it("moves ?view=events with filters to /activity, stripping view", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?view=events&agent=scout&connection_ids=3`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/activity`);
		expect(router.state.location.search).toMatchObject({
			agent: "scout",
			connection_ids: 3,
		});
		expect(router.state.location.search.view).toBeUndefined();
		unmount();
	}, 20_000);

	it("moves a content permalink (?content_ids=) to /activity", async () => {
		// The backend builds event permalinks as /{owner}/memory?content_ids=N.
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?content_ids=4242`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/activity`);
		expect(String(router.state.location.search.content_ids)).toBe("4242");
		unmount();
	}, 20_000);

	it("moves an entity events drill (?entity_id=) to /activity", async () => {
		const { router, unmount } = await mountAt(`/${OWNER}/memory?entity_id=7`);
		expect(router.state.location.pathname).toBe(`/${OWNER}/activity`);
		expect(String(router.state.location.search.entity_id)).toBe("7");
		unmount();
	}, 20_000);

	it("keeps ?view=entities scopes on /memory, stripping view", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?view=entities&type=company`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search).toMatchObject({ type: "company" });
		expect(router.state.location.search.view).toBeUndefined();
		unmount();
	}, 20_000);

	it("lets a browse_path entity detail win over stray event keys", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?browse_path=company/acme&run_ids=5`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
